    z_t3393_t* boxed = (z_t3393_t*)z_xmalloc(sizeof(z_t3393_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_T4137_TAG_0;
    result.data = boxed;
